        if isinstance(uprev, float) or isinstance(uprev, int):
            if math.isfinite(uprev):
                uprev = _clamp(float(uprev), 0.0, 1.0)
            else:
                uprev = None
        else:
            uprev = None
        first = True
        if isinstance(yf_prev, float) or isinstance(yf_prev, int):
            if math.isfinite(yf_prev):
                first = False
        if first:
            yf = y
            rf = 0.0
        else:
            yf_prev = _clamp(float(yf_prev), 0.0, 1.0)
            Tf = 1.8
