            yf = (1.0 - a) * yf_prev + a * y
            yf = _clamp(yf, 0.0, 1.0)
            raw_rate = (yf - yf_prev) / dt
            raw_rate = _clamp(raw_rate, -0.15, 0.15)
            Tr = 1.8
            b = dt / (Tr + dt)
            rf = (1.0 - b) * rf_prev + b * raw_rate
            rf = _clamp(rf, -0.15, 0.15)
        Tp = 3.2
        y_pred = yf + Tp * rf
        y_pred = _clamp(y_pred, 0.0, 1.0)
        base = 1.10 * target
        base = _clamp(base, 0.0, 0.75)
        err_pred = target - y_pred
        err = target - yf
        err_pred = _clamp(err_pred, -1.0, 1.0)
        err = _clamp(err, -1.0, 1.0)
        Kp = 0.75
        P = Kp * err_pred
        P = _clamp(P, -0.45, 0.45)
        Kd = 0.6
        D = -Kd * rf
        D = _clamp(D, -0.20, 0.20)
        if yf > 0.80:
            s_max = 0.20
        elif yf > 0.78:
            s_max = 0.40
        elif yf > 0.75:
            s_max = 0.55
        elif yf > 0.72:
            s_max = 0.75
        else:
            s_max = 0.92
        if y > 0.85:
            if s_max > 0.20:
                s_max = 0.20
        Ki = 0.40
        if abs(err) < 0.015 and yf > 0.55 and yf < 0.65:
            Ki = 0.12
        integ = integ_prev
        if abs(err) < 0.30:
            u_test = base + P + integ + D
            blocked_high = (u_test > s_max) and (err > 0)
            blocked_low = (u_test < 0.0) and (err < 0)
            if not blocked_high and not blocked_low:
                integ = integ + Ki * err * dt
                integ = _clamp(integ, -0.40, 0.40)
        u = base + P + integ + D
