                u = uprev + maxd
            elif u < uprev - maxd:
                u = uprev - maxd
        if not math.isfinite(u):
            u = 0.0
        u = _clamp(u, 0.0, 1.0)
        ns = {"yf": float(_clamp(yf, 0.0, 1.0)), "rf": float(_clamp(rf, -0.15, 0.15)), "integ": float(_clamp(integ, -0.40, 0.40)), "uprev": float(u)}
        return (float(u), ns)
    except Exception:
        try:
            return (0.0, {"yf": 0.6, "rf": 0.0, "integ": 0.0, "uprev": 0.0})
        except Exception:
            return (0.0, {})
